// The instrument picker for the soundfont build: an "Import" button, a font
// selector and a preset selector, replacing JummBox's built-in preset dropdown.
//
// This lives in its own file rather than inside SongEditor because it is the only
// part of the instrument panel that is genuinely new; everything else in Stage 4 is
// hiding controls that no longer do anything.

import { Instrument, Synth, LoadedFont, PresetInfo } from "../synth/synth";
import { SongDocument } from "./SongDocument";
import { ChangeSoundFont } from "./changes";
import { HTML } from "imperative-html/dist/esm/elements-strict";

const { button, div, input, option, select, span } = HTML;

export class SoundFontInstrumentPicker {
    public readonly container: HTMLDivElement;

    private readonly _importButton: HTMLButtonElement = button({ style: "width: 100%; margin: 2px 0;" }, "Import SoundFont...");
    private readonly _fileInput: HTMLInputElement = input({ type: "file", accept: ".sf2,.sf3,.dls", multiple: "multiple", style: "display: none;" });
    private readonly _fontSelect: HTMLSelectElement = select({ style: "width: 100%;" });
    private readonly _presetSelect: HTMLSelectElement = select({ style: "width: 100%;" });
    private readonly _statusRow: HTMLDivElement = div({ style: "padding: 2px 0; text-align: center; font-size: 11px; opacity: 0.75;" });
    private readonly _diagnoseButton: HTMLButtonElement = button(
        { style: "width: 100%; margin: 2px 0; font-size: 11px; opacity: 0.7;", title: "Print this instrument's tuning and font mapping to the browser console." },
        "Diagnose tuning");

    private readonly _fontRow: HTMLDivElement;
    private readonly _presetRow: HTMLDivElement;

    /** Guards against re-entrant change events while the selects are repopulated. */
    private _rebuilding: boolean = false;
    /**
     * Font list revision, so the selects are only rebuilt when the set changes.
     * The initial value must be something the real signature can never equal --
     * an empty string is what "no fonts loaded" produces, so starting there meant
     * the very first render was skipped and the dropdown came up empty.
     */
    private _renderedFontSignature: string = "\u0000never";
    private _renderedPresetFontId: string | null = null;

    constructor(private readonly _doc: SongDocument) {
        this._fontRow = div({ class: "selectRow" },
            span({ class: "tip", style: "cursor: default;" }, "Font:"),
            div({ class: "selectContainer", style: "width: 100%;" }, this._fontSelect),
        );
        this._presetRow = div({ class: "selectRow" },
            span({ class: "tip", style: "cursor: default;" }, "Preset:"),
            div({ class: "selectContainer", style: "width: 100%;" }, this._presetSelect),
        );
        this.container = div({ class: "editor-controls" },
            this._importButton,
            this._fileInput,
            this._fontRow,
            this._presetRow,
            this._statusRow,
            this._diagnoseButton,
        );

        this._importButton.addEventListener("click", (): void => {
            this._fileInput.value = "";
            this._fileInput.click();
        });
        this._fileInput.addEventListener("change", this._whenFilesChosen);
        this._fontSelect.addEventListener("change", this._whenFontChanged);
        this._presetSelect.addEventListener("change", this._whenPresetChanged);
        this._diagnoseButton.addEventListener("click", (): void => {
            const engine = this._synth.soundFontEngine;
            if (engine == null) return;
            console.log(engine.diagnose(this._doc.channel, this._doc.getCurrentInstrument()));
            this._statusRow.textContent = "Tuning report printed to the browser console.";
        });
    }

    private get _synth(): Synth {
        return this._doc.synth;
    }

    private _currentInstrument(): Instrument | null {
        const song = this._doc.song;
        if (song == null || this._doc.channel >= song.channels.length) return null;
        const channel = song.channels[this._doc.channel];
        const index: number = this._doc.getCurrentInstrument();
        if (index >= channel.instruments.length) return null;
        return channel.instruments[index];
    }

    private _whenFilesChosen = (): void => {
        const files: FileList | null = this._fileInput.files;
        if (files == null || files.length == 0) return;
        const names: string[] = [];
        for (let i: number = 0; i < files.length; i++) names.push(files[i].name);
        this._statusRow.textContent = "Loading " + names.join(", ") + "...";

        // ensureSoundFontEngine() starts the audio context, which browsers only allow
        // from a user gesture -- this click is one.
        const engine = this._synth.ensureSoundFontEngine();
        const loads: Promise<LoadedFont>[] = [];
        for (let i: number = 0; i < files.length; i++) {
            const file: File = files[i];
            loads.push(file.arrayBuffer().then((data: ArrayBuffer): Promise<LoadedFont> => engine.loadFont(data, file.name)));
        }
        Promise.all(loads).then((fonts: LoadedFont[]): void => {
            this._statusRow.textContent = "";
            // Assign the first newly imported font to the selected instrument, which
            // is almost always what someone means by importing while a channel is
            // selected. The others simply become available in the Font list.
            const instrument: Instrument | null = this._currentInstrument();
            if (instrument != null && fonts.length > 0) {
                this._doc.record(new ChangeSoundFont(this._doc, fonts[0].id, 0));
            }
            this._doc.notifier.changed();
        }, (error: unknown): void => {
            this._statusRow.textContent = "Could not load: " + (error instanceof Error ? error.message : String(error));
        });
    }

    private _whenFontChanged = (): void => {
        if (this._rebuilding) return;
        const value: string = this._fontSelect.value;
        this._doc.record(new ChangeSoundFont(this._doc, value == "" ? null : value, 0));
    }

    private _whenPresetChanged = (): void => {
        if (this._rebuilding) return;
        const instrument: Instrument | null = this._currentInstrument();
        if (instrument == null || instrument.soundFontId == null) return;
        this._doc.record(new ChangeSoundFont(this._doc, instrument.soundFontId, parseInt(this._presetSelect.value, 10) || 0));
    }

    public updateDisplay(): void {
        const instrument: Instrument | null = this._currentInstrument();
        if (instrument == null) return;
        const engine = this._synth.soundFontEngine;
        const fonts: LoadedFont[] = engine != null ? engine.listFonts() : [];

        this._rebuilding = true;
        try {
            const signature: string = fonts.map((f: LoadedFont): string => f.id).join(",");
            if (signature != this._renderedFontSignature) {
                this._renderedFontSignature = signature;
                this._fontSelect.textContent = "";
                this._fontSelect.appendChild(option({ value: "" }, fonts.length == 0 ? "(import a soundfont)" : "(none)"));
                for (const font of fonts) {
                    this._fontSelect.appendChild(option({ value: font.id }, font.name));
                }
                // Force the preset list to rebuild against the new font set.
                this._renderedPresetFontId = null;
            }

            const fontId: string | null = instrument.soundFontId;
            const font: LoadedFont | null = (fontId != null && engine != null) ? engine.getFont(fontId) : null;
            this._fontSelect.value = font != null ? font.id : "";

            if (this._renderedPresetFontId != (font != null ? font.id : null)) {
                this._renderedPresetFontId = font != null ? font.id : null;
                this._presetSelect.textContent = "";
                if (font != null) {
                    for (const preset of font.presets) {
                        this._presetSelect.appendChild(option({ value: preset.index },
                            preset.name + (preset.isDrum ? " [drum]" : "")));
                    }
                }
            }
            this._presetRow.style.display = (font != null && font.presets.length > 0) ? "" : "none";
            if (font != null) {
                const index: number = Math.max(0, Math.min(font.presets.length - 1, instrument.soundFontPreset));
                this._presetSelect.value = String(index);
            }

            if (fontId != null && font == null) {
                // The song names a font that has not been imported in this session.
                this._statusRow.textContent = "This instrument's soundfont is missing. Import it to hear this channel.";
            } else if (fonts.length == 0) {
                this._statusRow.textContent = "";
            } else if (font != null) {
                const preset: PresetInfo | undefined = font.presets[instrument.soundFontPreset];
                this._statusRow.textContent = preset != null && preset.isDrum
                    ? "Drum preset: keys are kit pieces, not pitches."
                    : "";
            } else {
                this._statusRow.textContent = "No soundfont on this instrument - it will be silent.";
            }
        } finally {
            this._rebuilding = false;
        }
    }
}
